input.sparql:
SELECT ?s ?class ?ts WHERE {
  ?a brick:hasIdentifier "AHU03" .
  ?s brick:isPointOf ?a .
  ?s a ?class .
  OPTIONAL { ?s brick:hasTimeseriesId ?ts . }
}

SELECT ?point ?class ?ts WHERE {
  ?point brick:isPointOf ?ah .
  FILTER (CONTAINS(str(?ah), "AHU03")) .
  ?point a ?class .
  OPTIONAL { ?point brick:hasTimeseriesId ?ts . }
}

SELECT ?point ?class ?ts WHERE {
  ?point a brick:Electric_Power_Sensor .
  OPTIONAL { ?point brick:hasTimeseriesId ?ts . }
  FILTER (CONTAINS(str(?point), "AHU03")) .
}
